INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('24510f13-502f-4ec8-ba7a-3fc255ba9b16', '21feff02-016d-46e2-bb9d-c27495133b1b', '103. óra: Gyakorlóóra. A terület és a térfogat mérése', 'Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "52171738-52c5-420e-8f9c-9d610a6162e1", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "146832c2-5009-418a-b3ee-de87ffc3ddd0", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "adc231eb-ac17-490f-b546-e1f6a092b903", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "b9f42924-1f86-4f7d-bd5f-0da1481b12c3", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "87bce388-40f7-4397-8935-92e1aaabd77d", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "7fda2cb3-9f04-45ab-93da-7fc8ac49b4d4", "text": "Igaz", "isCorrect": true}, {"id": "ab6de94e-4b55-473e-a1e4-453bb1a71569", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a50131b-9dc0-47cc-a393-e4fa0f8ca1e2", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "561f2722-da11-4747-a489-5666e5fe5857", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('64765e25-8df1-44e0-b0e3-37ae128c3907', '21feff02-016d-46e2-bb9d-c27495133b1b', '104. óra: A sokszögek területe', 'Négyzet, téglalap és derékszögű háromszög területe (T).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "37b61eec-7ab9-4d46-a16b-e74aacced23b", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "ebe628c2-1a79-4472-8dcd-2638f4891766", "text": "T = a * b", "isCorrect": true}, {"id": "fa24cd8e-ddcd-4b39-9060-a2d50f6e4b95", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "03911e43-149d-461c-ac13-fff4c95e9fdb", "text": "T = a + b", "isCorrect": false}, {"id": "8312341b-cb02-44ed-8195-9151fc4f7686", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "7d67f838-c6bb-4332-b5cf-79f022db6966", "text": "Mi a négyzet területének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "52b3a315-301f-4dea-956b-8cadf9ddfab3", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "9588bb67-55e3-4de1-aed0-b5c8f511baa2", "text": "T = 4 * a", "isCorrect": false}, {"id": "92edb2c9-8f82-4186-ae0d-e759d3bbb8fa", "text": "T = 2 * a", "isCorrect": false}, {"id": "d298f9f9-fde8-4d10-9fd9-3d64ad932c6d", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "d62463c2-74c2-4e74-bba4-da38b5777f2a", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "d6ba2940-a13a-444f-86a8-9cdbd286613f", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "c7fc5960-223c-413c-941b-5f937a4cd22d", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "a1ec203d-02ff-427e-a4fe-b3ae795677ea", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "ef585af3-4e5f-4dcc-be2c-e5001d45b10b", "text": "T = a * b", "isCorrect": false}, {"id": "0c0c57aa-8c4f-4a12-b7d5-f1990191e3c3", "text": "T = a + b", "isCorrect": false}, {"id": "d443a4de-9032-4fd6-9b68-dc82e9565549", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "0f69dc5d-4cc0-4105-9817-daec6f7802f6", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "e43d8740-5b57-43a2-aec2-4664d7c9ce81", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "d2e12d31-9c46-4ad7-9a94-a095b24b7aca", "text": "Igaz", "isCorrect": true}, {"id": "b341bd6c-6610-4921-b4d4-9dca53754eb8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1253d852-32ab-43a5-87d7-300ab8ccc84a', '21feff02-016d-46e2-bb9d-c27495133b1b', '105. óra: Feladatmegoldás', 'Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "adaf9965-17a4-4223-bd85-7e78a4c99275", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "42a90267-3319-459c-b2d1-f6f9d0eac99e", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "8157b254-fe83-4f53-aa55-02c6d23fea4e", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "2a15f4a4-4224-463d-9c7c-141160f64d00", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "cdc5e5ff-a490-42e3-9d4f-85ece0df4e4c", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "f148abe5-0ae2-4527-bb0d-96422221c99f", "text": "Igaz", "isCorrect": true}, {"id": "5228eb23-51b1-4076-8d74-dfd19ba476d6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "daf7ead7-2b23-4c2c-8a88-20724a84486f", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "4690cd14-17f1-41bf-9e3c-3cb0deb72fa1", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "8a2f300d-310f-4867-afb6-3fb080a0d039", "text": "Igaz", "isCorrect": true}, {"id": "72de55a6-08f9-447d-b182-63b5b03dacc4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bda6aefe-cab4-4e75-ac06-c6ffb5919e70', '21feff02-016d-46e2-bb9d-c27495133b1b', '106. óra: Alakzatok a térben', 'Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "066327bc-848d-4a30-9933-4d9f45421303", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5c98fd86-943a-422c-8e8a-1b02df9d031a", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "f704dfe1-df97-4820-b45c-45eb5a20224a", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "edf381a7-bec8-48f8-bf79-133f8b2c507f", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "dd087d9d-0554-4146-96a2-135e71189c87", "text": "Igaz", "isCorrect": true}, {"id": "d3b350af-8537-44d8-a928-16e8ce8d6952", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "44d5eafc-e20a-41c5-956b-9df0d02b8350", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "7a58f2fd-3940-4d69-af52-018ee2f19418", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "534a6c33-8147-464b-8de7-e82532e02fc9", "text": "Háromszögek", "isCorrect": false}, {"id": "f6f3d6bb-15b6-4322-8ace-5bdd489e1551", "text": "Körök", "isCorrect": false}, {"id": "8eb0f8c1-f8e5-496e-9e3b-7582cea70658", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "faa4966d-a9a4-47e2-aa48-7d78592a4ab5", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "c8c45f03-434e-42e8-898d-83cee5a1b222", "text": "Igaz", "isCorrect": true}, {"id": "0784d9d6-269e-476c-96b5-b8a368c4ad2b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ef80f9d7-f33e-4d06-8a75-02225aab3259", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a662641a-5a05-412b-a6c7-babde2874a36', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b39f5f2d-4c3e-4b75-818e-2077eb32dfb3", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "42b0a6c6-d459-435c-b619-5dd4f0916081", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "2177e29c-71bf-447e-95d3-60adb6b2fc10", "text": "V = 6 * a²", "isCorrect": false}, {"id": "34660e69-a11c-4ee5-ba38-990045d2e3d3", "text": "V = 12 * a", "isCorrect": false}, {"id": "28df1be7-ccd4-4b34-80d6-2aefca72c690", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "423dd54f-aaea-4e87-ba8d-90673ee28d2a", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "843d4bba-78fa-4d23-9b7a-b6ed67cf1e21", "text": "V = a * b * c", "isCorrect": true}, {"id": "2b668303-23f7-4e8c-a17f-8d403aa6006c", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "007db31f-0ba3-45f9-8d37-495632ffdbc7", "text": "V = a * b", "isCorrect": false}, {"id": "61c70420-b11d-4d6b-84e7-4cf6a563743f", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "90e8bd4d-b503-46dd-b0c3-dc2f9a0f5e1e", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "ce9244f6-d587-4855-aa90-c88d50e40aeb", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "fdf63392-ec95-4a8b-a9c6-b5cbdad44769", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "3686aa7e-8789-48e7-9ad7-5e39add76039", "text": "Igaz", "isCorrect": true}, {"id": "1fd20c31-54da-4f87-a0b2-ba18406b99c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c72f87f-562e-494b-9aec-c99c06292045", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "158ceff2-ebc4-4a93-be6b-5cecc57afec2", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());